const d = $json;
const clean = (v) => v === undefined || v === null || v === '' ? 'Not provided' : String(v);
const email = clean(d.email);
const userMessage = `HabitPulse daily check-in for ${clean(d.name)}

Main goal: ${clean(d.goal)}
Habits: ${clean(d.habits)}
Today's activity/workout: ${clean(d.activity)}
Sleep: ${clean(d.sleep)} hours
Water intake: ${clean(d.water)} litres
Missed habits/days: ${clean(d.missed)}
Mood: ${clean(d.mood)}`;
return [{json:{...d,email,name:clean(d.name),goal:clean(d.goal),habits:clean(d.habits),activity:clean(d.activity),sleep:clean(d.sleep),water:clean(d.water),missed:clean(d.missed),mood:clean(d.mood),userMessage}}];

const d = $('Prepare HabitPulse Data').first().json;
const ai = $json.output || $json.text || $json.response || JSON.stringify($json);
const esc = (s) => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');
const html = `<!doctype html><html><body style="margin:0;background:#f4f7fb;font-family:Arial,sans-serif;color:#1f2937"><div style="max-width:680px;margin:30px auto;background:#fff;border-radius:16px;overflow:hidden;box-shadow:0 4px 18px rgba(0,0,0,.08)"><div style="padding:28px;background:#111827;color:#fff"><h1 style="margin:0;font-size:28px">HabitPulse</h1><p style="margin:8px 0 0;opacity:.85">Personal Habit &amp; Fitness Accountability Coach</p></div><div style="padding:28px"><p>Hello <strong>${esc(d.name)}</strong>,</p><div style="padding:18px;background:#f8fafc;border-radius:12px;margin:18px 0"><h2 style="margin-top:0">Your Check-in</h2><p><strong>Goal:</strong> ${esc(d.goal)}</p><p><strong>Habits:</strong> ${esc(d.habits)}</p><p><strong>Activity:</strong> ${esc(d.activity)}</p><p><strong>Sleep:</strong> ${esc(d.sleep)} hours</p><p><strong>Water:</strong> ${esc(d.water)} litres</p><p><strong>Missed:</strong> ${esc(d.missed)}</p><p><strong>Mood:</strong> ${esc(d.mood)}</p></div><h2>Your HabitPulse Coaching</h2><div style="line-height:1.7">${esc(ai)}</div><hr style="border:0;border-top:1px solid #e5e7eb;margin:26px 0"><p style="font-size:12px;color:#6b7280">HabitPulse provides general wellness and accountability guidance only. It is not medical advice.</p></div></div></body></html>`;
return [{json:{to:d.email,subject:`HabitPulse Coaching Report — ${d.name}`,html,aiResponse:ai}}];
